<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import {api,apiMessage} from '@/api/client';
import {isAndroid,isDesktop,isNativeClient,nativeInvoke} from '@/desktop';
import {useAuthStore} from '@/stores/auth';
import {disableDeviceReminders,enableDeviceReminders,nativeReminderStatus,notificationDefaults,type ReminderPreferences,type ReminderDevice,type ReminderNativeStatus} from '@/reminders';
const auth=useAuthStore(),prefs=reactive(notificationDefaults());
const devices=ref<ReminderDevice[]>([]),native=ref<ReminderNativeStatus|null>(null),ready=ref(false),busy=ref(false),message=ref(''),error=ref('');
async function load(){error.value='';try{const p=(await api.get<ReminderPreferences>('/reminders/preferences')).data;Object.assign(prefs,p);devices.value=(await api.get<ReminderDevice[]>('/reminders/devices')).data;native.value=await nativeReminderStatus();ready.value=true;}catch(e){error.value=apiMessage(e);}}
async function save(){busy.value=true;error.value='';message.value='';try{Object.assign(prefs,(await api.put('/reminders/preferences',{...prefs,primaryDeviceId:prefs.primaryDeviceId||null})).data);message.value='提醒规则已保存。原生端会在下一次联网核对时读取新规则，其他设备不是即时推送。';}catch(e){error.value=apiMessage(e);}finally{busy.value=false;}}
async function toggle(){busy.value=true;error.value='';try{if(native.value?.enabled){await disableDeviceReminders();message.value='本设备的系统提醒已关闭。';}else{native.value=await enableDeviceReminders(auth.user!.id);message.value='本设备已启用系统提醒，只有已打开的规则会投递。授权有效期为30天，到期须本人重新开启。';}await load();}catch(e){error.value=apiMessage(e);native.value=await nativeReminderStatus().catch(()=>null);}finally{busy.value=false;}}
async function revoke(device:ReminderDevice){if(!confirm('关闭这台设备的后续提醒？已显示的通知可能要在该设备手动移除。'))return;busy.value=true;try{if(device.id===native.value?.deviceId)await disableDeviceReminders();else await api.delete(`/reminders/devices/${device.id}`);await load();}catch(e){error.value=apiMessage(e);}finally{busy.value=false;}}
async function exact(){await nativeInvoke('reminder_exact_permission');message.value='请自行在系统页面选择是否允许精确提醒；返回后点击重新读取状态。拒绝时仍使用可能延迟的系统调度。';}
onMounted(load);
</script>
<template><div class="page reminders-page"><section class="page-head"><div><h1>系统通知与事项提醒</h1><p>规则随账号同步；是否在本设备通知，由你决定。</p></div><button class="btn" :disabled="busy" @click="load">重新读取状态</button></section>
<p v-if="error" role="alert" class="error-text">{{error}}</p><p v-if="message" role="status" class="success-text">{{message}}</p>
<section class="section device-summary"><div><h2>本设备</h2><p v-if="!isNativeClient()">网页版仅提供打开页面且联网时的站内提醒，不承诺关闭浏览器后投递。下方规则可同步至原生客户端。</p><p v-else>{{native?.enabled?'已开启系统提醒':'系统提醒未开启'}} · {{native?.permission===true?'系统允许通知':native?.permission===false?'系统通知尚未授权':'系统许可状态无法读取，投递由系统决定'}}<template v-if="isAndroid()"> · {{native?.exact?'允许精确调度':'系统调度可能延迟'}}</template></p><p>默认关闭。首次开启才申请通知权限，不自动修改系统安全或省电设置。</p></div><div class="button-row" v-if="isNativeClient()"><button class="btn primary" :disabled="busy||!ready" @click="toggle">{{native?.enabled?'关闭本设备提醒':'开启本设备提醒'}}</button><button v-if="isAndroid()&&!native?.exact" class="btn" :disabled="busy" @click="exact">申请精确提醒</button></div></section>
<form v-if="ready" @submit.prevent="save"><section class="section reminder-rules"><article><h2>周期任务提前提醒</h2><label class="check"><input type="checkbox" v-model="prefs.advanceEnabled"/>提前提醒</label><label>提前分钟<input type="number" v-model.number="prefs.advanceMinutes" min="1" max="120" required/></label><p>只提醒有开始时间、尚未开始的任务；没有时间的任务不会被擅自安排。</p></article><article><h2>到点开始提醒</h2><label class="check"><input type="checkbox" v-model="prefs.startEnabled"/>到点提醒</label><p>到计划开始时间了，是否开始？已经开始、暂停或完成的事项不会再次作为“未开始”提醒。</p></article><article><h2>今日待办收尾</h2><label class="check"><input type="checkbox" v-model="prefs.todoEnabled"/>待办收尾提醒</label><label>每日时间<input type="time" v-model="prefs.todoTime" required/></label><p>仅当天仍有未完成待办时提醒，不把长期目标路线算作今日欠账。</p></article></section>
<section class="section reminder-options"><div><h2>时间与隐私</h2><label>提醒时区<select v-model="prefs.zone"><option value="Asia/Shanghai">北京时间 Asia/Shanghai</option><option value="UTC">UTC</option><option value="Asia/Tokyo">东京 Asia/Tokyo</option><option value="America/New_York">纽约 America/New_York</option><option value="Europe/London">伦敦 Europe/London</option></select></label><label class="check"><input type="checkbox" v-model="prefs.hideDetails"/>隐藏通知中的事项正文</label><p>默认不展示任务标题。Android锁屏通知使用私密可见性；系统仍可能按自己的设置展示。</p></div><div><h2>免打扰与主设备</h2><label class="check"><input type="checkbox" v-model="prefs.quietEnabled"/>启用免打扰</label><div class="time-pair"><label>开始<input type="time" v-model="prefs.quietFrom" required/></label><label>结束<input type="time" v-model="prefs.quietUntil" required/></label></div><label>主提醒设备<select v-model="prefs.primaryDeviceId"><option :value="null">各已开启设备分别提醒</option><option v-for="d in devices.filter(x=>x.enabled)" :key="d.id" :value="d.id">{{d.label}}</option></select></label><p>免打扰期间跳过，不在结束后一口气补发。主设备选择在联网核对时生效。</p></div></section><button class="btn primary" :disabled="busy">保存提醒规则</button></form>
<section class="section"><h2>已授权的提醒设备</h2><p v-if="!devices.length">尚未开启任何提醒设备。</p><article v-for="d in devices" :key="d.id" class="device-row"><div><strong>{{d.label}}</strong><p>{{d.platform}} · {{d.enabled?'已授权':'已关闭'}} · 到期 {{new Date(d.expiresAt).toLocaleString()}}</p></div><button v-if="d.enabled" class="btn" :disabled="busy" @click="revoke(d)">关闭这台设备提醒</button></article></section>
<section class="section"><h2>投递边界</h2><p>发出前联网核对，离线或状态无法核实时不发“尚未完成”通知。出现本地未同步操作时，本设备提醒会关闭，避免按旧云端状态通知；同步完成后可手动重新开启，不会自动清理队列。</p><p>正常后台可由系统唤醒；关机、系统强停、通知被禁用、省电策略或超过5分钟的延迟可能导致本次提醒跳过。其他端改期、完成或关闭提醒不是远程即时推送，下一次核对后才生效。</p><p v-if="isDesktop()">Windows使用当前用户的单次计划任务唤醒，无需管理员权限或常驻轮询；只有用户保持登录时投递。点击通知使用同服务器网页版查看事项，浏览器可能需要另行登录。</p><p v-if="isAndroid()">Android重启后由系统重新核对并安排；强行停止后需本人重新打开。精确时间由系统授权和节电策略决定。点击通知返回计划舱，不直接修改任务。</p><router-link to="/overview#reminder-settings">站内提醒设置</router-link></section></div></template>
<style scoped>
.reminders-page p{line-height:1.8;color:var(--muted)}.device-summary,.device-row{display:flex;justify-content:space-between;align-items:center;gap:20px}.device-row{padding:16px 0;border-bottom:1px solid var(--line)}.reminder-rules{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0}.reminder-rules article{padding:20px;border:1px solid var(--line)}.reminder-rules h2{font-size:1.1rem}.reminder-rules label,.reminder-options label{display:grid;gap:8px;margin:16px 0}.reminder-rules .check,.reminder-options .check{display:flex;align-items:center;gap:10px}.reminder-rules input[type=number]{max-width:140px}.reminder-options{display:grid;grid-template-columns:1fr 1fr;gap:32px}.time-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:700px){.device-summary,.device-row{align-items:stretch;flex-direction:column}.reminder-rules,.reminder-options{grid-template-columns:minmax(0,1fr)}.device-summary .button-row{display:grid}.page-head .btn{width:100%}}
</style>
